using System;using System.IO;using UnityEngine;using UnityEngine.UI;using UnityEditor;using IdleIntelligence.Runtime;
namespace IdleIntelligence.Editor {
 public static class BuildRewardPresentation {
  const string Fx="Assets/IdleIntelligence/Resources/PixelUI/";const string Art="Assets/IdleIntelligence/Resources/";
  static void Save(UnityEngine.Object obj,string path){var previous=AssetDatabase.LoadMainAssetAtPath(path);if(previous==null)AssetDatabase.CreateAsset(obj,path);else{EditorUtility.CopySerialized(obj,previous);UnityEngine.Object.DestroyImmediate(obj);}}
  static Sprite Slice(string file,string name,Rect rect){var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(Art+file+".png");var sprite=Sprite.Create(tex,rect,new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect);sprite.name=name;Save(sprite,Fx+name+".asset");return AssetDatabase.LoadAssetAtPath<Sprite>(Fx+name+".asset");}
  static Sprite PixelPart(string name,bool steam){int w=steam?24:64,h=steam?24:48;var tex=new Texture2D(w,h,TextureFormat.RGBA32,false){filterMode=FilterMode.Point};tex.SetPixels(new Color[w*h]);void Box(int x,int y,int width,int height,Color c){for(int j=y;j<y+height;j++)for(int i=x;i<x+width;i++)if(i>=0&&j>=0&&i<w&&j<h)tex.SetPixel(i,j,c);}var edge=GameTheme.Hex("08131F");var steel=GameTheme.Hex("496579");var light=GameTheme.Hex("A1C0D3");if(steam){Box(9,0,5,5,light);Box(6,4,10,5,light*.8f);Box(4,8,15,5,light*.6f);Box(3,12,7,5,light*.35f);Box(14,15,5,4,light*.2f);}else{Box(20,18,24,30,edge);Box(22,20,20,28,steel);Box(24,20,3,28,light);Box(35,20,4,28,GameTheme.Hex("172C3B"));for(int i=0;i<5;i++)Box(26,22+i*5,10,2,edge);Box(6,2,52,18,edge);Box(8,4,48,14,steel);Box(10,15,44,2,light);Box(11,5,42,3,GameTheme.Hex("243D4E"));Box(20,8,24,5,edge);Box(22,9,20,3,GameTheme.Accent);foreach(int x in new[]{11,49}){Box(x,9,4,4,edge);Box(x+1,11,2,1,light);}}tex.Apply();Save(tex,Fx+name+"-texture.asset");var saved=AssetDatabase.LoadAssetAtPath<Texture2D>(Fx+name+"-texture.asset");var sprite=Sprite.Create(saved,new Rect(0,0,w,h),Vector2.one*.5f,100,0,SpriteMeshType.FullRect);Save(sprite,Fx+name+".asset");return AssetDatabase.LoadAssetAtPath<Sprite>(Fx+name+".asset");}

  static Sprite Crank(){var source=new Texture2D(2,2);source.LoadImage(File.ReadAllBytes(Art+"CapsuleMachine.png"));var tex=new Texture2D(294,294,TextureFormat.RGBA32,false){filterMode=FilterMode.Point};var colors=new Color[294*294];for(int y=0;y<294;y++)for(int x=0;x<294;x++){var c=source.GetPixel(x+365,y+390);if(new Vector2(x-147,y-147).sqrMagnitude>138*138)c=Color.clear;colors[y*294+x]=c;}tex.SetPixels(colors);tex.Apply();UnityEngine.Object.DestroyImmediate(source);Save(tex,Fx+"crank-pixels.asset");var saved=AssetDatabase.LoadAssetAtPath<Texture2D>(Fx+"crank-pixels.asset");var sprite=Sprite.Create(saved,new Rect(0,0,294,294),Vector2.one*.5f,100,0,SpriteMeshType.FullRect);Save(sprite,Fx+"gumball-crank.asset");return AssetDatabase.LoadAssetAtPath<Sprite>(Fx+"gumball-crank.asset");}
  static Sprite Pressure(int frame){var tex=new Texture2D(48,48,TextureFormat.RGBA32,false){filterMode=FilterMode.Point};var colors=new Color[48*48];float radius=7+frame*3;for(int y=0;y<48;y++)for(int x=0;x<48;x++){float ax=Math.Abs(x-24),ay=Math.Abs(y-24);float distance=Math.Max(Math.Max(ax,ay),(ax+ay)*.7071f);if(distance<=radius&&distance>=radius-1.4f)colors[y*48+x]=Color.white;}tex.SetPixels(colors);tex.Apply();string name="pressure-"+frame;Save(tex,Fx+name+"-pixels.asset");var saved=AssetDatabase.LoadAssetAtPath<Texture2D>(Fx+name+"-pixels.asset");Save(Sprite.Create(saved,new Rect(0,0,48,48),Vector2.one*.5f,100,0,SpriteMeshType.FullRect),Fx+name+".asset");return AssetDatabase.LoadAssetAtPath<Sprite>(Fx+name+".asset");}
  static void Place(RectTransform r,Vector2 pos,Vector2 size){r.anchorMin=r.anchorMax=Vector2.one*.5f;r.pivot=Vector2.one*.5f;r.anchoredPosition=pos;r.sizeDelta=size;}
  public static void Build(){foreach(string file in new[]{"ShopChests","CapsuleMachine","MobileSprites","DeliveryDrone"}){string path=Art+file+".png";var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer==null)throw new InvalidOperationException("Missing original art "+path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.filterMode=FilterMode.Point;importer.mipmapEnabled=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.maxTextureSize=2048;importer.SaveAndReimport();}
   var art=ScriptableObject.CreateInstance<PresentationArt>();art.ChestBody=new Sprite[4];art.ChestLid=new Sprite[4];for(int i=0;i<4;i++){int x=i%2*627,y=i<2?627:0;art.ChestBody[i]=Slice("ShopChests","chest-body-"+i,new Rect(x,y,627,290));art.ChestLid[i]=Slice("ShopChests","chest-lid-"+i,new Rect(x,y+290,627,337));}art.Machine=Slice("CapsuleMachine","gumball-machine",new Rect(0,0,1024,1536));art.Crank=Crank();art.Door=Slice("CapsuleMachine","gumball-door",new Rect(410,210,204,160));var mobile=AssetDatabase.LoadAssetAtPath<Texture2D>(Art+"MobileSprites.png");art.Capsule=Slice("MobileSprites","capsule-closed",new Rect(mobile.width*.5f,mobile.height*.5f,mobile.width*.25f,mobile.height*.5f));art.OpenCapsule=Slice("MobileSprites","capsule-open",new Rect(mobile.width*.75f,mobile.height*.5f,mobile.width*.25f,mobile.height*.5f));art.Drone=Slice("DeliveryDrone","delivery-drone",new Rect(0,0,1180,887));art.Piston=PixelPart("forge-piston",false);art.Steam=PixelPart("forge-steam",true);art.Blueprint=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/IdleIntelligence/Art/ui-resource-4.asset");art.Pressure=new Sprite[6];for(int i=0;i<6;i++)art.Pressure[i]=Pressure(i);Save(art,Fx+"PresentationArt.asset");
   var root=WorkshopUIFactory.Node("RewardStage",null);var r=root.AddComponent<RewardStage>();r.Shade=WorkshopUIFactory.Node("QuietReceiptBackdrop",root.transform,typeof(Image)).GetComponent<Image>();WorkshopUIFactory.Fill(r.Shade.rectTransform);r.Shade.raycastTarget=false;r.Stage=(RectTransform)WorkshopUIFactory.Node("ReceiptComposition",root.transform).transform;r.Stage.anchorMin=new Vector2(.04f,.5f);r.Stage.anchorMax=new Vector2(.96f,.5f);r.Stage.sizeDelta=new Vector2(0,420);r.Stage.anchoredPosition=new Vector2(0,0);
   Image Image(string name){var im=WorkshopUIFactory.Node(name,r.Stage,typeof(Image)).GetComponent<Image>();im.raycastTarget=false;im.preserveAspect=true;Place(im.rectTransform,Vector2.zero,Vector2.one*100);return im;}r.Body=Image("MachineBody");r.Lid=Image("MechanicalLid");r.Crank=Image("MachineCrank");r.Door=Image("DispenserDoor");r.Capsule=Image("DispensedCapsule");r.Rewards=WorkshopUIFactory.Node("ActualRewards",r.Stage).transform;WorkshopUIFactory.Fill((RectTransform)r.Rewards);
   var portrait=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/IdleIntelligence/Prefabs/ItemPortrait.prefab");r.Portrait=UnityEngine.Object.Instantiate(portrait,r.Rewards).GetComponent<ItemPortrait>();r.Portrait.name="ReceiptItem";r.Portrait.Button.interactable=false;foreach(var g in r.Portrait.GetComponentsInChildren<Graphic>())g.raycastTarget=false;Place((RectTransform)r.Portrait.transform,new Vector2(0,48),Vector2.one*164);
   r.Heading=WorkshopUIFactory.Label("ReceiptHeading",r.Stage,"",20);UnityEngine.Object.DestroyImmediate(r.Heading.GetComponent<LayoutElement>());Place(r.Heading.rectTransform,new Vector2(0,192),new Vector2(290,44));r.Heading.alignment=TextAnchor.MiddleCenter;r.Heading.font=GameTheme.Bold;
   r.ShortenButton=WorkshopUIFactory.Button("ShortenReward",r.Stage,"",null);UnityEngine.Object.DestroyImmediate(r.ShortenButton.GetComponent<LayoutElement>());Place((RectTransform)r.ShortenButton.transform,new Vector2(0,-177),new Vector2(118,44));r.CloseButton=WorkshopUIFactory.Button("CloseReward",r.Stage,"×",null);UnityEngine.Object.DestroyImmediate(r.CloseButton.GetComponent<LayoutElement>());var cr=(RectTransform)r.CloseButton.transform;cr.anchorMin=cr.anchorMax=Vector2.one;cr.anchoredPosition=new Vector2(-22,-22);cr.sizeDelta=Vector2.one*44;PrefabUtility.SaveAsPrefabAsset(root,Fx+"RewardStage.prefab");UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();Debug.Log("REWARD_PRESENTATION_READY original chest, cabinet and capsule layers + owned piston/steam");
  }
 }
}
